CREATE TABLE backup_snapshots (backup_id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES owner_users(owner_id),state TEXT NOT NULL CHECK(state IN ('BUILDING','VERIFIED','FAILED')),cut_seq INTEGER NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,counts_json TEXT NOT NULL CHECK(json_valid(counts_json)),manifest_json TEXT CHECK(manifest_json IS NULL OR json_valid(manifest_json)),manifest_hash TEXT,error_code TEXT,UNIQUE(owner_id,backup_id));
CREATE TABLE backup_chunks (owner_id TEXT NOT NULL,backup_id TEXT NOT NULL,table_name TEXT NOT NULL,chunk_index INTEGER NOT NULL,cursor INTEGER NOT NULL,next_cursor INTEGER,count INTEGER NOT NULL,sha256 TEXT NOT NULL,columns_json TEXT NOT NULL CHECK(json_valid(columns_json)),bytes INTEGER NOT NULL,FOREIGN KEY(owner_id,backup_id) REFERENCES backup_snapshots(owner_id,backup_id),PRIMARY KEY(owner_id,backup_id,table_name,cursor),UNIQUE(owner_id,backup_id,table_name,chunk_index));
CREATE TRIGGER backup_barrier_owner_users_insert BEFORE INSERT ON owner_users WHEN EXISTS(SELECT 1 FROM maintenance_state WHERE singleton=1 AND barrier_token IS NOT NULL AND barrier_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'BACKUP_MUTATION_PAUSED'); END;
